(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+wx1, my = y+wy1;
  const wx2 = Math.sin(mx*0.025-t*0.15)*8 + Math.cos(my*0.02+t*0.4)*6;
  const wy2 = Math.cos(my*0.03+t*0.2)*8 + Math.sin(mx*0.022-t*0.3)*6;
  const sx = mx+wx2, sy = my+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const [sX,sY,f,sp] of src){
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS2 += Math.sin(d*f*1.5 - t*sp*1.3 + 0.5)*0.5;
    iS2 += Math.cos(d*f*1.2 + t*sp*0.8 + 2.1)*0.5;
  }
  const n = src.length;
  const act = (aS+aS2)/n, inh = (iS+iS2)/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+sy*0.05-t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.3
    + Math.sin(dist*0.03-ang*5+t*0.8)*0.2;
  const preReact = act - inh*0.7 + bg*0.3 + spiral;
  const feedback = Math.sin(preReact*3.0 + t*0.5)*0.15;
  const reaction = Math.tanh((preReact + feedback)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.25-sy*0.35-t*2.5)*0.1;
  const blend = reaction*0.6 + cell*0.2 + micro*0.2, v = blend*0.5+0.5;
  const pal = [
    [5,12,45],[12,45,85],[18,85,120],[25,140,135],[55,175,120],
    [140,195,80],[210,190,60],[220,150,55],[200,100,60],
    [160,60,70],[100,30,60],[55,18,55],[25,12,48],[5,12,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge = Math.abs(reaction)>0.7?1.15:1.0;
  const glow = Math.max(0, reaction)*0.3;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*20)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*30)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*50)|0
  ];
}
